head.script:
scwin.trigger2_onclick = function(e) {
	imports("uiplugin.popup");
	WebSquare.util.openPopup("/sample/common_link/p_popup_litewindow_WPF-1811_(WSQ-2918)_sub.xml", {
		id: "pop1",
		type: "litewindow",
		width: 500,
		height: 500,
		top: 50,
		left: 50,
		popupName: "test",
		modal: true,
		useIFrame: false,
		resizable: false,
		status: false,
		menubar: false,
		scrollbars: scroll,
		title: 'test222',
		useMaxmimize: true,
		useControl: true,
		foldOnMinimized: true
	});
};

scwin.getStyle = function() {
	var style = window.getComputedStyle(pop1_header_control);
	return style.getPropertyValue('right') == "0px";
};

scwin.checkVal1 = function() {
	return window.getComputedStyle((document.getElementById('pop1_minimize') || document.getElementById('mf_pop1_minimize'))).getPropertyValue('display') == "inline-block";
};

scwin.checkVal2 = function() {
	return window.getComputedStyle((document.getElementById('pop1_restore') || document.getElementById('mf_pop1_restore'))).getPropertyValue('display') == "inline-block";
};
